options.script:
// Parameters Initialization
var data_list = [];
var trace_no = 0
let xAxis = "$x_axis";
let yAxis = "$y_axis";
let zAxis = "$z_axis";
let scatterType = "$scatter_type";

// Create internal variables
var scatter_type = variables.scatter_type

if(scatter_type == '2D'){
	// Parameters Initialization
	var serie_x_index_list = []
	var serie_y_index_list = []

	// Create internal variables
	var x_axis_tmp = variables.x_axis
	var y_axis_tmp = variables.y_axis

	// Convert x_axis to list if needed
	if(Array.isArray(x_axis_tmp)){
		var x_axis = x_axis_tmp
	} else {
		var x_axis = x_axis_tmp.split(',')
	}

	// Convert y_axis to list if needed
	if(Array.isArray(y_axis_tmp)){
		var y_axis = y_axis_tmp
	} else {
		var y_axis = y_axis_tmp.split(',')
	}

	// Check if x axis and y axis tags selected matched 
	if(x_axis.length != y_axis.length){
		var warn_msg = "[Warning] Selected tags in X and Y axis do not matched"
		console.log(warn_msg)
	} else {
		var warn_msg = ""

		// Get x axis series index
		for(xi=0, yi=0; xi < x_axis.length, yi < y_axis.length; xi++, yi++){
			for(serie_index=0; serie_index < data.series.length; serie_index++){
				// Get serie name
				var series_name = data.series[serie_index].name;

				// Get x axis index value on series list
				if(series_name.search(x_axis[xi]) != -1){
					serie_x_index_list.push(serie_index)
				}

				// Get y axis index value on series list
				if(series_name.search(y_axis[yi]) != -1){
					serie_y_index_list.push(serie_index)
				}
			}
		}

		// Create traces
		//for(sxi=0, syi=0; sxi < serie_x_index_list.length, syi < serie_y_index_list.length; sxi++, syi++){
		for(sxi=0; sxi < serie_x_index_list.length; sxi++){
			// Create trace
			var trace = {
				type: "scatter",
				mode: "markers",
				marker: {"size": 5},
				name: "Trace " + trace_no.toString(),
				x: data.series[serie_x_index_list[sxi]].fields[1].values.buffer,
				y: data.series[serie_y_index_list[sxi]].fields[1].values.buffer
			};

			// Add to data list
			data_list.push(trace);

			// Increase trace number
			trace_no += 1;
		}
	}

	// Create layout object
	layout = {
		"title": warn_msg,
		"font": {"size": 10},
		"margin": {"b": 30, "t": 30},
		"paper_bgcolor": "rgba(0,0,0,0)",
		"plot_bgcolor": "rgba(0,0,0,0)",
		"xaxis": {
			"autorange": true,
			"showspikes": true,
			"title": {
				"font": {
					"size": 15
				},
				"text": "X"
			},
			"type": "linear"
		},
		"yaxis": {
			"autorange": true,
			"showspikes": true,
			"title": {
				"font": {
					"size": 15
				},
				"text": "Y"
			},
			"type": "linear"
		}
	}
} else if(scatter_type == '3D'){
	// Parameters Initialization
	var serie_x_index_list = []
	var serie_y_index_list = []
	var serie_z_index_list = []

	// Create internal variables
	var x_axis_tmp = variables.x_axis
	var y_axis_tmp = variables.y_axis
	var z_axis_tmp = variables.z_axis

	// Convert x_axis to list if needed
	if(Array.isArray(x_axis_tmp)){
		var x_axis = x_axis_tmp
	} else {
		var x_axis = x_axis_tmp.split(',')
	}

	// Convert y_axis to list if needed
	if(Array.isArray(y_axis_tmp)){
		var y_axis = y_axis_tmp
	} else {
		var y_axis = y_axis_tmp.split(',')
	}

	// Convert z_axis to list if needed
	if(Array.isArray(z_axis_tmp)){
		var z_axis = z_axis_tmp
	} else {
		var z_axis = z_axis_tmp.split(',')
	}

	// Check if x axis and y axis tags selected matched 
	if((x_axis.length != y_axis.length) || 
		(x_axis.length != z_axis.length) || 
		(y_axis.length != z_axis.length)){
		var warn_msg = "[Warning] Selected tags in X, Y and Z axis do not matched"
		console.log(warn_msg)
	} else {
		var warn_msg = ""

		// Get x axis series index
		for(xi=0, yi=0, zi=0; xi < x_axis.length, yi < y_axis.length, zi < z_axis.length; xi++, yi++, zi++){
			for(serie_index=0; serie_index < data.series.length; serie_index++){
				// Get serie name
				var series_name = data.series[serie_index].name;

				// Get x axis index value on series list
				if(series_name.search(x_axis[xi]) != -1){
					serie_x_index_list.push(serie_index)
				}

				// Get y axis index value on series list
				if(series_name.search(y_axis[yi]) != -1){
					serie_y_index_list.push(serie_index)
				}

				// Get z axis index value on series list
				if(series_name.search(z_axis[zi]) != -1){
					serie_z_index_list.push(serie_index)
				}
			}
		}

		// Create traces
		for(sxi=0; sxi < serie_x_index_list.length; sxi++){
			// Create trace
			var trace = {
				type: "scatter3d",
				mode: "markers",
				opacity:0.8,
				marker: {"size": 4},
				name: "Trace " + trace_no.toString(),
				x: data.series[serie_x_index_list[sxi]].fields[1].values.buffer,
				y: data.series[serie_y_index_list[sxi]].fields[1].values.buffer,
				z: data.series[serie_z_index_list[sxi]].fields[1].values.buffer
			};

			// Add to data list
			data_list.push(trace);

			// Increase trace number
			trace_no += 1;
		}
	}

	// Create layout object
	layout = {
		"title": warn_msg,
		"font": {"size": 10},
		"margin": {"b": 30, "t": 30},
		"scene": {
			"aspectmode": "auto",
			"aspectratio": {
				"x": 1,
				"y": 1,
				"z": 1
			},
			"camera": {
				"center": {
					"x": 0,
					"y": 0,
					"z": 0
				},
				"eye": {
					"x": 2.208561547005106,
					"y": 1.515397763939418,
					"z": 1.5183744915217012
				},
				"projection": {
					"type": "perspective"
				},
				"up": {
					"x": 0,
					"y": 0,
					"z": 1
				}
			},
			"xaxis": {
				"autorange": true,
				"showgrid": true,
				"showspikes": true,
				"title": {
					"font": {
							"size": 15
					},
					"text": "X"
				},
				"type": "linear"
			},
			"yaxis": {
				"autorange": true,
				"showgrid": true,
				"showspikes": true,
				"title": {
					"font": {
							"size": 15
					},
					"text": "Y"
				},
				"type": "linear"
			},
			"zaxis": {
				"autorange": true,
				"showgrid": true,
				"showspikes": true,
				"title": {
					"font": {
						"size": 15
					},
					"text": "Z"
				},
				"type": "linear"
			}
		}
	}
} else {
	var warn_msg = "[Error] Unsupported scatter plot type selected"
	console.log(warn_msg)

	// Create layout object
	layout = {
		"title": warn_msg,
		"font": {"size": 10},
		"margin": {"b": 30, "t": 30},
		"paper_bgcolor": "rgba(0,0,0,0)",
		"plot_bgcolor": "rgba(0,0,0,0)",
	}
}

return {data:data_list,layout:layout};

