for(serie_index=0; serie_index < data.series.length; serie_index++){
	// Get serie name
	var series_name = data.series[serie_index].name;
	feature_name_list = series_name.split(".")
	feature_name = feature_name_list[feature_name_list.length - 1]

	// Create trace
	var trace = {
