console.log(data_list)
// Create layout object
layout = {
	"margin": {"b": 30, "t": 30},
	"xaxis": {
		"automargin": true,
		"title": {
			"font": {
				"size": 10
			}
		},
		"type": "linear"
	},
	"yaxis": {
		"automargin": true,
