// Parameters Initialization
var data_list = [];
var dimensions_list = [];

// Create internal variables
var input_tags_selected_tmp = variables.input_features.replaceAll("\"", "")
var output_tags_selected_tmp = variables.anomaly_score.replaceAll("\"", "")
var model_measurement_inputs_clean = variables.model_measurement_inputs
var model_measurement_outputs_clean = variables.model_measurement_outputs

// Get input tags selected
if(Array.isArray(input_tags_selected_tmp)){
	var input_tags_selected = input_tags_selected_tmp
} else {
	var input_tags_selected = input_tags_selected_tmp.split(',')
}

// Get output tags selected
if(Array.isArray(output_tags_selected_tmp)){
	var output_tags_selected = output_tags_selected_tmp
} else {
	var output_tags_selected = output_tags_selected_tmp.split(',')
}

// Get series index
for(serie_index=0; serie_index < data.series.length; serie_index++){
	// Get serie name
	var series_name = data.series[serie_index].name;

	// Clean serie name
	var series_name_clean_tmp = series_name.replaceAll(model_measurement_inputs_clean, "")
	var series_name_clean = series_name_clean_tmp.replaceAll(model_measurement_outputs_clean, "")

	// Get only input features
	for(input_index=0; input_index < input_tags_selected.length; input_index++){
		if(series_name.indexOf(input_tags_selected[input_index]) != -1){		
			// Add to dimensions list
			dimensions_list.push({label: input_tags_selected[input_index], values: data.series[serie_index].fields[1].values.buffer});
		}
	}
}

// Get series index
for(serie_index=0; serie_index < data.series.length; serie_index++){
	// Get serie name
	var series_name = data.series[serie_index].name;

	// Clean serie name
	var series_name_clean_tmp = series_name.replaceAll(model_measurement_inputs_clean, "")
	var series_name_clean = series_name_clean_tmp.replaceAll(model_measurement_outputs_clean, "")

	// Get only output features
	for(output_index=0; output_index < output_tags_selected.length; output_index++){
		if(series_name.indexOf(output_tags_selected[output_index]) != -1){		
			// Add to dimensions list
			dimensions_list.push({label: output_tags_selected[output_index], values: data.series[serie_index].fields[1].values.buffer});
		}
	}
}

// Create trace
var trace = {
	type: "parcoords",
	dimensions: dimensions_list
};

// Add to data list
data_list.push(trace);

// Create layout object
layout = {
	"margin": {"b": 20, "t": 35, "l": 90},
	"font": {"size": 11},
	"paper_bgcolor": "rgba(0,0,0,0)",
	"plot_bgcolor": "rgba(0,0,0,0)"
}

return {data:data_list,layout:layout};
